import random
import unittest

from counting import BudgetExceeded, Ops, Tracked as T, CountingSeq as Seq, plain
from auctionhouse.summary import manifest_is_sorted


def oracle(a):
    return all(not (a[i + 1] < a[i]) for i in range(len(a) - 1))


def wrap(a):
    return ([T(x) for x in a],)

def small_args(rng):
    return (sorted([rng.randrange(0, 20) for _ in range(rng.randrange(0, 12))]) if rng.random() < 0.5 else [rng.randrange(0, 20) for _ in range(rng.randrange(0, 12))],)


class CorrectnessTests(unittest.TestCase):
    def test_matches_the_reference_on_random_inputs(self):
        rng = random.Random(1000)
        for _ in range(120):
            args = small_args(rng)
            self.assertEqual(manifest_is_sorted(*args), oracle(*args), args)

    def test_works_with_instrumented_values(self):
        rng = random.Random(1001)
        for _ in range(40):
            args = small_args(rng)
            self.assertEqual(plain(manifest_is_sorted(*wrap(*args))), oracle(*args), args)

    def test_empty_inputs(self):
        empty = tuple([] for _ in range(1))
        self.assertEqual(manifest_is_sorted(*empty), oracle(*empty))

