import unittest

from counting import BudgetExceeded, Ops, Tracked as T, CountingSeq as Seq, plain
from dispatch.picks import lightest_parcel


def oracle(a):
    return min(a) if a else None


def wrap(a):
    return ([T(x) for x in a],)

def small_args(rng):
    return ([rng.randrange(0, 50) for _ in range(rng.randrange(0, 20))],)


class CorrectnessTests(unittest.TestCase):
