import random
import unittest

from counting import BudgetExceeded, Ops, Tracked as T, CountingSeq as Seq, plain
from dispatch.picks import lightest_parcel


def oracle(a):
    return min(a) if a else None


def wrap(a):
    return ([T(x) for x in a],)

def big_args(rng, n):
    return ([rng.randrange(0, 10 * n) for _ in range(n)],)


class PerformanceTests(unittest.TestCase):
    def test_cost_grows_with_the_input(self):
        rng = random.Random(1011)
        n = 5500
        args = big_args(rng, n)
        wrapped = wrap(*args)
        limit = 4 * n
        Ops.reset()
        Ops.budget = limit * 20
        try:
            got = lightest_parcel(*wrapped)
        except BudgetExceeded:
            self.fail("PERF: gave up after %d comparisons for %d items (limit %d): the function sorts everything although a selection or a single pass is enough" % (Ops.budget, n, limit))
        finally:
            Ops.budget = None
        ops = Ops.total()
        self.assertEqual(plain(got), oracle(*args))
        self.assertLessEqual(ops, limit, "PERF: %d comparisons for %d items (limit %d): the function sorts everything although a selection or a single pass is enough" % (ops, n, limit))

